import math
import numpy as np
from scipy.optimize import least_squares

_params = None

def fit(train_rows):
    global _params
    def residual(p):
        k, a = p
        return np.array([k*r['u_now'] + (r['x_now'] - k*r['u_now'])*math.exp(-a*r['H']) - r['y'] for r in train_rows])
    result = least_squares(residual, [2.0, 1.0], bounds=([-10.0, 0.0], [10.0, 20.0]))
    _params = result.x

def predict(row):
    k, a = _params
    return float(k*row['u_now'] + (row['x_now'] - k*row['u_now'])*math.exp(-a*row['H']))
